/* Mind Garden v2.3: one navigation bar, immersive garden welcome,
   searchable games library and guided daily activities. No framework required. */
(function(){
 'use strict';
 const home=document.getElementById('home'),legacyNav=document.getElementById('nav');
 const top=home.querySelector('.top'),hero=document.getElementById('hero');
 const oldDaily=document.getElementById('dailyStart');if(oldDaily)oldDaily.remove();
 const library=document.createElement('section');library.id='gameLibrary';library.className='hidden';
 const children=Array.from(home.children);let afterHero=false;
 children.forEach(el=>{if(el===hero){afterHero=true;return}if(el===legacyNav||el===top)return;if(el.classList.contains('sub')||afterHero)library.appendChild(el)});
 home.appendChild(library);
 const dash=document.createElement('section');dash.id='welcomeDashboard';dash.setAttribute('aria-label','Welcome to Mind Garden');home.insertBefore(dash,library);
 const nav=document.createElement('nav');nav.id='unifiedNav';nav.setAttribute('aria-label','Main navigation');home.insertBefore(nav,dash);
 // Keep garden growth visible, but never let its large SVG appear before the welcome page.
 function closeNavMenu(focus=false){const menu=document.getElementById('navMenu'),button=document.getElementById('navMore');if(!menu||!button)return;const wasOpen=!menu.classList.contains('hidden');menu.classList.add('hidden');button.setAttribute('aria-expanded','false');button.setAttribute('aria-label',T('Open menu','打开菜单'));if(focus&&wasOpen)button.focus()}
 document.addEventListener('keydown',e=>{if(e.key==='Escape')closeNavMenu(true)});
 document.addEventListener('click',e=>{if(!e.composedPath().includes(nav))closeNavMenu()});
 const progressStrip=document.createElement('section');progressStrip.id='gardenProgressStrip';progressStrip.setAttribute('aria-label','My garden progress');home.insertBefore(progressStrip,library);progressStrip.appendChild(hero);
 const progressDisplay=document.createElement('div');progressDisplay.id='progressDisplay';progressDisplay.className='progress-summary';progressStrip.appendChild(progressDisplay);
 const T=(a,b)=>window.MindGardenLocale.pair(a,b);
 function icon(kind){
  const parts={
   seed:'<ellipse cx="16" cy="20" rx="6" ry="8" fill="#bd8c55" stroke="#754a29"/><path d="M15 22Q12 11 21 7" fill="none" stroke="#638f48" stroke-width="2"/><path d="M18 11Q19 3 27 4Q27 11 18 11" fill="#9bc967"/>',
   sprout:'<path d="M16 28V15" stroke="#55936b" stroke-width="2.5"/><path d="M16 19Q3 19 4 7Q17 7 16 19" fill="#8dbb66"/><path d="M16 14Q17 3 29 5Q27 16 16 14" fill="#4f9570"/>',
   bud:'<path d="M16 30V15M16 25Q7 25 7 20Q15 19 16 25" stroke="#6ba573" fill="#6ba573" stroke-width="2"/><path d="M16 3C4 7 8 20 16 20C24 20 28 7 16 3Z" fill="#e395a5"/><path d="M9 17Q16 23 23 17" fill="none" stroke="#5a9870" stroke-width="2"/>',
   opening:'<path d="M16 30V15" stroke="#6ba573" stroke-width="2"/><path d="M16 17C-3 15 5 1 16 10C20-5 32 7 23 17C33 27 16 30 16 17C3 30-3 15 16 17" fill="#e29caa"/><circle cx="16" cy="16" r="4" fill="#f5cd6d"/>',
   bloom:'<g fill="#f3d081"><ellipse cx="16" cy="7" rx="5" ry="7"/><ellipse cx="16" cy="25" rx="5" ry="7"/><ellipse cx="7" cy="16" rx="7" ry="5"/><ellipse cx="25" cy="16" rx="7" ry="5"/><ellipse cx="9" cy="9" rx="6" ry="5" transform="rotate(45 9 9)"/><ellipse cx="23" cy="23" rx="6" ry="5" transform="rotate(45 23 23)"/></g><circle cx="16" cy="16" r="6" fill="#946133"/>',
   person:'<circle cx="16" cy="9" r="6"/><path d="M4 29v-3a12 12 0 0 1 24 0v3Z"/>',
   edit:'<path d="M5 22 22 5l5 5-17 17-7 2Z M19 8l5 5"/>',
   trash:'<path d="M5 8h22M12 8V4h8v4M8 8l2 21h12l2-21M14 13v11m4-11v11"/>',
   eye:'<path d="M2 16q14-20 28 0-14 20-28 0Z"/><circle cx="16" cy="16" r="4"/>',
   butterfly:'<path d="M16 25V9M16 15C-1-5 0 24 14 20C0 30 13 34 16 22M16 15C33-5 32 24 18 20C32 30 19 34 16 22M16 9l-4-5m4 5 4-5"/>',
   scenery:'<rect x="3" y="5" width="26" height="23" rx="3"/><circle cx="22" cy="12" r="3"/><path d="M4 24l8-9 7 7 4-4 6 6"/>',
   games:'<rect x="4" y="8" width="24" height="18" rx="6"/><path d="M8 16h8m-4-4v8m9-5h.1m3 5h.1"/>',
   together:'<circle cx="11" cy="10" r="4"/><circle cx="23" cy="12" r="3"/><path d="M3 27v-4a8 8 0 0 1 16 0v4m2-9a6 6 0 0 1 8 6v3"/>',
   progress:'<path d="M5 5v23h23M11 23v-7m7 7V9m7 14V4"/>',
   trophy:'<path d="M9 4h14v8a7 7 0 0 1-14 0ZM9 7H4v4a6 6 0 0 0 7 6m12-10h5v4a6 6 0 0 1-7 6m-5 2v8m-6 0h12"/>',
   next:'<path d="M5 16h22m-9-9 9 9-9 9"/>',
   skip:'<path d="M6 6l15 10L6 26ZM26 6v20"/>',
   easier:'<path d="M5 16h22"/>',
   grid:'<rect x="4" y="4" width="9" height="9" rx="2"/><rect x="19" y="4" width="9" height="9" rx="2"/><rect x="4" y="19" width="9" height="9" rx="2"/><rect x="19" y="19" width="9" height="9" rx="2"/>',
   options:'<path d="M13 3h6l1 4 3 2 4-1 3 5-3 3v3l3 3-3 5-4-1-3 2-1 3h-6l-1-3-3-2-4 1-3-5 3-3v-3l-3-3 3-5 4 1 3-2Z"/><circle cx="16" cy="17" r="5"/>',
   home:'<path d="M3 15L16 4l13 11M7 13v15h18V13M13 28v-9h6v9"/>',
   language:'<path d="M3 7h15M10 3v4M6 8q2 8 11 12M15 8q-2 8-11 14M19 28l5-15 5 15m-8-5h6"/>',
   sun:'<circle cx="16" cy="16" r="6"/><path d="M16 2v4m0 20v4M2 16h4m20 0h4M6 6l3 3m14 14 3 3M6 26l3-3M23 9l3-3"/>',
   moon:'<path d="M26 21A12 12 0 0 1 11 6a12 12 0 1 0 15 15Z"/>',
   menu:'<path d="M5 8h22M5 16h22M5 24h22"/>',
   pause:'<path d="M11 7v18M21 7v18" stroke-width="4"/>',
   play:'<path d="M10 5l17 11-17 11Z"/>',
   reset:'<path d="M7 10a11 11 0 1 1-2 12M7 4v8h8"/>',
   sound:'<path d="M4 12h6l7-6v20l-7-6H4Z M22 11a8 8 0 0 1 0 10M26 7a14 14 0 0 1 0 18"/>',
   muted:'<path d="M4 12h6l7-6v20l-7-6H4Z M22 12l7 8m0-8-7 8"/>',
   music:'<path d="M13 23V6l14-3v17M13 9l14-3"/><ellipse cx="8" cy="24" rx="5" ry="4"/><ellipse cx="22" cy="21" rx="5" ry="4"/>'
  };
  return '<svg class="garden-icon" viewBox="0 0 32 32" aria-hidden="true" '+(['seed','sprout','bud','opening','bloom'].includes(kind)?'':'fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"')+'>'+(parts[kind]||parts.sprout)+'</svg>';
 }
 window.MindGardenIcon=icon;
 function renderBed(){
  const bed=document.getElementById('livingGarden');if(!bed)return;
  const player=me(),points=Math.max(0,Math.min(60,player.gr||0)),stages=gstage(points),type=player.fl||'mixed';
  let stems='',leaves='';
  const positions=[[91,102],[205,106],[121,70],[178,64],[65,137],[231,140],[146,46],[104,129],[194,131],[131,101],[166,100],[151,136]];
  for(let i=0;i<12;i++){
   const [x,y]=positions[i],stage=stages[i],kind=type==='mixed'?FLK[i%6]:type;
   if(stage>1){const top=stage===2?y+34:y;stems+='<path d="M150 222Q'+(x+(150-x)*.2)+' 165 '+x+' '+top+'" fill="none" stroke="'+(i%2?'#5e8965':'#3e7058')+'" stroke-width="2.6" stroke-linecap="round"/>';
   stems+='<path d="M'+((x+150)/2)+' 170q-28-3-22-22q24 2 22 22m4-12q22-21 28-8q-8 16-28 8" fill="#79a481" opacity=".85"/>';}
   stems+='<g class="bed-plant" data-stage="'+stage+'" data-flower="'+kind+'">'+(stage>=4?head(kind,x,y,stage===4?.72:1.02):stage===3?'<ellipse cx="'+x+'" cy="'+y+'" rx="5" ry="9" fill="#d99aa9"/>':'')+'</g>';
  }
  for(let i=0;i<5;i++){const x=80+i*35,y=125+(i%2)*17;leaves+='<path d="M150 222Q'+x+' 180 '+x+' '+y+'" stroke="#638c74" stroke-width="2" fill="none"/><g fill="'+(i%2?'#9cba94':'#719a85')+'"><ellipse cx="'+(x-7)+'" cy="'+(y+10)+'" rx="6" ry="12" transform="rotate(-42 '+(x-7)+' '+(y+10)+')"/><ellipse cx="'+(x+7)+'" cy="'+(y+27)+'" rx="6" ry="12" transform="rotate(42 '+(x+7)+' '+(y+27)+')"/></g>';}
  bed.innerHTML='<figcaption><span class="journey-eyebrow">'+T('GROWN BY YOU','由你培育')+'</span><h2>'+T('Your growing bouquet','你的成长花束')+'</h2></figcaption><svg viewBox="0 0 300 255" role="img" aria-label="'+T('Your bouquet: ','你的花束：')+points+'/60"><defs><radialGradient id="bouquetGlow"><stop stop-color="#dcebd6" stop-opacity=".75"/><stop offset="1" stop-color="#dcebd6" stop-opacity="0"/></radialGradient></defs><circle cx="150" cy="135" r="118" fill="url(#bouquetGlow)"/>'+leaves+stems+'<path d="M137 209q13 5 27 0l-3 9q-12 4-21 0Z" fill="#d7ad84"/><path d="M148 214q-26-20-28-2q7 11 28 2m6 0q25-20 26-2q-7 11-26 2m-5 2-11 21m16-21 9 19" fill="none" stroke="#c9a07b" stroke-width="3" stroke-linecap="round"/></svg><p>'+ (points<12?T('A little greenery today. More flowers with every game.','今日的一点绿意，每一局都让花束更丰盛。'):T('Your chosen flowers flourish as you play.','随着你的游戏，心爱的花朵逐渐绽放。'))+'</p>';
  const chosen=document.createElement('p');chosen.className='bouquet-selection';chosen.innerHTML='<span class="bouquet-selection-icon" aria-hidden="true"><svg viewBox="0 0 36 36">'+(type==='mixed'?FLK.map((kind,i)=>head(kind,6+(i%3)*12,9+Math.floor(i/3)*18,.28)).join(''):head(type,18,18,.8))+'</svg></span><span>'+T('Selected: ','已选择：')+(type==='mixed'?T('Mixed','混合'):T(FL[type].n,({sunflower:'向日葵',daisy:'雏菊',tulip:'郁金香',rose:'玫瑰',orchid:'兰花',hibiscus:'扶桑花'})[type]))+'</span>';bed.append(chosen);
  window.MindGardenBouquet?.attach(bed,points,type);
 }
 function renderProgress(){
  const player=me(),points=Math.max(0,Math.min(60,player.gr||0));
  const labels=[['Seeds','种子'],['Sprouts','嫩芽'],['Buds','花苞'],['Opening','绽放'],['Full bloom','盛开']],icons=['seed','sprout','bud','opening','bloom'],targets=[12,24,36,48,60];
  const next=targets.findIndex(x=>points<x),day=dstr(),mins=Math.round((player.log||[]).filter(x=>x.d===day).reduce((a,x)=>a+x.s,0)/60),streak=curStreak(player);
  const headline=next<0?T('Your garden is in full bloom','你的花园已盛开'):T('Next: ','下一步：')+T(...labels[next]);
  progressDisplay.innerHTML='<figure id="livingGarden" class="bouquet-card"></figure><div class="journey-main"><div class="journey-heading"><div><p class="journey-eyebrow">'+T('Bouquet ','花束 ')+((player.gs||0)+1)+'</p><h2>'+headline+'</h2><p class="journey-next">'+(next<0?T('Every flower is flourishing. Beautiful work!','每朵花都已盛开，真棒！'):T('Just '+(targets[next]-points)+' more growth points to reach this stage.','再获得 '+(targets[next]-points)+' 点成长值，即可达到这个阶段。'))+'</p></div><div class="journey-score"><strong>'+points+'<span> / 60</span></strong><small>'+T('growth points','成长值')+'</small></div></div><div class="journey-meter" role="progressbar" aria-label="'+T('Garden growth','花园成长')+'" aria-valuemin="0" aria-valuemax="60" aria-valuenow="'+points+'"><span style="width:'+(points/60*100)+'%"></span></div><ol class="journey-stages">'+labels.map((it,i)=>'<li class="'+(points>=targets[i]?'earned':i===next?'next':'')+'"'+(i===next?' aria-current="step"':'')+'><span class="journey-stage-icon" aria-hidden="true">'+icon(icons[i])+'</span><b>'+T(...it)+'</b><small>'+targets[i]+' '+T('pts','点')+(points>=targets[i]?' ✓':'')+'</small></li>').join('')+'</ol></div><aside class="journey-today"><div class="journey-stats"><div><span>'+T('Today','今天')+'</span><strong>'+mins+' <small>'+T('min','分钟')+'</small></strong></div><div><span>'+T('Day streak','连续天数')+'</span><strong>'+streak+' <small>'+T(streak===1?'day':'days','天')+'</small></strong></div></div><p class="journey-status">'+(player.last===day?T('✓ Today’s game is complete','✓ 今日游戏已完成'):T('Your next game helps your garden grow.','再玩一局，让你的花园继续成长。'))+'</p><button class="progress-flowers" type="button" id="progressFlowers">'+T('Choose my flowers','选择我的花朵')+' <span aria-hidden="true">↗</span></button>'+(points===60?'<button class="journey-new" id="progressNew">'+T('Grow another','再种一束')+'</button>':'')+'</aside>';
  document.getElementById('progressFlowers').onclick=()=>openFlw();
  if(document.getElementById('progressNew'))document.getElementById('progressNew').onclick=()=>{if(player.gr<60)return;player.bouquets=player.bouquets||[];player.bouquets.push({number:(player.gs||0)+1,flower:player.fl||'mixed',date:dstr()});player.gr=0;player.gs=(player.gs||0)+1;const choices=['mixed',...FLK];player.fl=choices[(choices.indexOf(player.fl||'mixed')+1)%choices.length];persist();renderHero()};
  const collection=document.createElement('button');collection.id='myGarden';collection.className='progress-flowers';collection.textContent=T('My Garden','我的花园');progressDisplay.querySelector('.journey-today').append(collection);
  collection.onclick=()=>{const saved=player.bouquets||[],items=[...saved];if(points===60)items.push({number:(player.gs||0)+1,flower:player.fl||'mixed',date:dstr()});overlay('<h2>'+T('My Garden','我的花园')+'</h2><div class="bouquet-collection">'+(items.length?items.map(b=>{const kind=FLK.includes(b.flower)?b.flower:'mixed';return '<figure><svg viewBox="0 0 100 100" role="img" aria-label="'+T('Completed bouquet','已完成花束')+'">'+[0,1,2,3,4,5].map((_,i)=>head(kind==='mixed'?FLK[i%FLK.length]:kind,25+i%3*25,25+Math.floor(i/3)*40,.8)).join('')+'</svg><figcaption>'+T('Bouquet ','花束 ')+Number(b.number)+'</figcaption></figure>'}).join(''):'<p>'+T('No completed bouquets','无已完成花束')+'</p>')+'</div>');};
  renderBed();
 }
 // Refresh both visible progress representations when the legacy engine changes flowers or resets growth.
 const legacyHero=window.renderHero;window.renderHero=function(){legacyHero();renderProgress()};

 const today=()=>dstr();let page='dashboard',daily=null,filter='all',collection='all',search='',length='standard';
 const META={sudoku:'logic',stroop:'attention',flags:'language',scene:'memory',gardenrhythm:'movement',followgardener:'movement',hawker:'studio',album:'studio',trail:'studio',sounds:'studio',teamgarden:'studio',melody:'studio',today:'everyday',foodknow:'everyday',localnews:'everyday',dots:'shapes',pets:'relax',spot:'attention',links:'logic',drawmemory:'memory',recall:'memory',jigsaw:'shapes',dominoes:'logic',bingo:'attention',pathways:'logic',sayings:'language',seq:'memory',miss:'memory',rem:'memory',shopping:'memory',story:'memory',num:'numbers',sum:'numbers',sub:'numbers',tbl:'numbers',cnt:'numbers',add:'numbers',money:'numbers',sort:'logic',odd:'logic',same:'logic',routine:'logic',place:'logic',shp:'shapes',clk:'shapes',time:'shapes',calendar:'shapes',order:'shapes',diff:'attention',count:'attention',find:'attention',visual:'attention',wrd:'language',wm:'language',pic:'language',related:'language'};
 const LABELS={movement:['Seated movement','坐姿动作'],studio:['New game previews','新游戏预览'],all:['All Games','全部游戏'],memory:['Memory','记忆'],attention:['Attention','观察'],logic:['Logic','逻辑'],language:['Language','语言'],numbers:['Numbers','数字'],shapes:['Shapes & time','图形与时间'],relax:['Cosy Corner','舒心角落'],everyday:['Everyday Life','日常生活']};
 const GAME_TIME={jigsaw:6,dominoes:8,bingo:5,pathways:5,sayings:4,seq:4,miss:4,rem:3,shopping:5,story:5,diff:5,visual:4,wrd:5,related:4};
 function navAction(action){if(action==='account')window.MindGardenAccount?.panel(window.MindGardenAccount.signedIn?undefined:'signin');else if(action==='daily')startDaily();else if(action==='mygames')window.MindGardenPersonal?.myGames();else if(action==='home')switchPage('dashboard');else if(action==='library')openLibrary();else if(action==='online')document.getElementById('bOnline').click();else if(action==='progress')window.openMyProgress();else if(action==='leaderboard')document.getElementById('bLb').click();else if(action==='family')document.getElementById('bFam').click();else if(action==='settings')document.getElementById('bSet').click();else if(action==='profile')document.getElementById('bPl').click();else if(action==='language')document.getElementById('bLang').click();else if(action==='nature')document.getElementById('homeNatureToggle')?.click();else if(action==='motion')document.getElementById('homeAnimationToggle')?.click();else if(action==='music')document.getElementById('bMus').click();else if(action==='theme'){document.getElementById('bSet').click();}else if(action==='quickguide')window.MindGardenV4?.openGuide();else if(action==='about')openInfo('about');else if(action==='contact')openInfo('contact');else if(action==='appearance'){save.mode=appearanceDark()?'light':'dark';persist();applyPrefs();syncAppearance();}}
 const appearanceMedia=matchMedia('(prefers-color-scheme: dark)');
 function appearanceDark(){const mode=document.documentElement.dataset.theme;return mode==='dark'||(mode!=='light'&&appearanceMedia.matches)}
 function syncAppearance(){const button=document.getElementById('navAppearance');if(!button)return;const dark=appearanceDark(),label=dark?T('Switch to light mode','切换到浅色模式'):T('Switch to dark mode','切换到深色模式');button.innerHTML=icon(dark?'moon':'sun');button.dataset.appearance=dark?'dark':'light';button.setAttribute('aria-label',label);button.title=(dark?T('Dark mode','深色模式'):T('Light mode','浅色模式'))+' · '+label}
 new MutationObserver(syncAppearance).observe(document.documentElement,{attributes:true,attributeFilter:['data-theme']});appearanceMedia.addEventListener('change',syncAppearance);
 function feedbackURL(embed=false){
  const value=document.querySelector('meta[name="'+(embed?'mind-garden-feedback-embed':'mind-garden-feedback')+'"]')?.content.trim();
  try{const u=new URL(value);return u.protocol==='https:'&&(u.hostname==='docs.google.com'&&u.pathname.startsWith('/forms/')||!embed&&u.hostname==='forms.gle')?u.href:''}catch{return ''}
 }
 function aboutExtras(){
  const setup=[
   ['Choose your language','选择语言','Open Menu → English / 中文, then select a language. The current choice has a check mark.','打开菜单 → English / 中文，再选择语言。当前语言显示勾号。'],
   ['Choose your player','选择玩家','Select Choose or add a player below. Give each person their own local player so their progress and preferences stay separate. A nickname is enough.','点击下方“选择或添加玩家”。为每个人建立独立的本地玩家，以分别保存进度与偏好设置。使用昵称即可。'],
   ['Make reading comfortable','调整阅读方式','Open Menu for text size and Display mode. T− / T+ adjusts size and ↺ restores 100%. More settings contains reading and contrast options.','打开菜单调整字号与显示模式。T− / T+调整大小，↺恢复100%。更多设置包含阅读与对比度选项。'],
   ['Choose sound and movement','选择声音与动画','Open Menu for Music, Background audio and Animation. Welcome videos have separate playback and sound controls.','打开菜单使用音乐、背景声音与动画。欢迎视频有独立的播放与声音控件。'],
   ['Try a first game','开始第一局','Choose Today’s Games for a guided activity, or browse All Games and choose a comfortable difficulty. Take a break whenever you like.','选择“今日游戏”体验引导活动，或浏览所有游戏并选择合适的难度。随时可以休息。'],
   ['Keep a backup','保存备份','After playing, use ☰ → Account settings → Saved data & backup → Player backup & import to download a JSON backup before moving devices or clearing browser data.','游戏后，可在“☰ → 账户设置 → 保存资料与备份 → 玩家备份与导入”中下载JSON备份。更换设备或清除浏览器数据前，请先备份。']
  ];
  const faq=[
   ['Is Players’ Progress my group account?','玩家进度是群组账户吗？','Players’ Progress summarises weekly progress for the loaded players. Signed in, it shows the account’s players; signed out, it shows this device’s players. It does not manage accounts. Open Leaderboard to compare games played and best times. Online room rankings are separate.','玩家进度概览已载入玩家的每周进度。登录后显示账户玩家；未登录时显示此设备玩家。它不管理账户。打开排行榜可比较已玩局数及最佳用时；在线房间排名另列。'],
   ['Will my preferences return when I sign in?','登录后会恢复我的偏好吗？','Yes. Sign in to your personal account, then choose your player if the account contains several. The profile restores appearance, text size, language, sound, scenery, home cards, chosen games and each game’s saved difficulty. Without an account, selecting the same player in this browser restores its local preferences. Renaming keeps the same profile. Personal photo, video and music files do not transfer to another device.','会。登录个人账户；若账户有多位玩家，再选择自己的玩家。资料会恢复外观、字号、语言、声音、景色、主页卡片、所选游戏及各游戏已存难度。无需账户，在同一浏览器选择原玩家也会恢复本地偏好。修改名称仍保留同一份资料。个人照片、视频和音乐文件不会传至其他设备。'],
   ['Will switching appearance change my scenery?','切换外观会更换景色吗？','Built-in scenery stays on the same place when switching light and dark mode. All nine sceneries use matching day and dusk images, including the new plateau, autumn lake, moon-gate terrace and stone bridge. Scenery arrows select a place for both modes. The larger, bold scenery name has a contrasting background in both appearances. Personal photos remain separate uploads for each appearance.','切换浅色与深色模式时，内置景色保持同一地点。九处景色均使用对应的日景与黄昏图，包括新高原、秋日山湖、月门露台及石桥。背景箭头会为两种模式选择同一地点。景色名称使用较大的粗体字，并在两种外观下配以对比鲜明的底色。个人照片仍按外观分别上传。'],
   ['Why do later levels feel different now?','现在较高关卡有何不同？','Balanced now uses the full 1–15 challenge scale instead of repeating ten settings. Later levels add rules such as picture-to-word pairs, reverse recall, shopping-list updates, route checkpoints and meaning questions. Some board sizes repeat for consolidation. Gentle deliberately keeps a smaller difficulty range with fresh content. Read the level preview before starting; practice does not save a score.','适中模式现在使用完整的1至15级挑战，不再重复十种设置。较高关卡加入图片与词语配对、倒序回忆、购物清单更新、路径检查点及含义理解等规则。部分棋盘大小会重复以巩固技能。轻松模式保留较小的难度范围，并更换内容。开始前请阅读关卡说明，练习不保存分数。'],
   ['Do I need to choose settings after every level?','每关结束后都需要重新选择设置吗？','No. Next level, Replay and Easier level start directly with saved choices. Open Settings (gear) on the result screen to adjust settings or choose Easier level. The settings screen hides the previous board and scenery. Move & Remember also continues to the next level with your chosen movements. Story questions only refer to events shown in the story. Boards adapt to the viewport; long content remains scrollable on small screens or with enlarged text.','不需要。“下一关”、“重玩本关”和“尝试较轻松关卡”会直接使用已保存的设置。需要调整或选择较轻松关卡时，请打开成绩页的“选项”。设置画面会隐藏上一局棋盘与背景。“动一动，记一记”也会沿用所选动作进入下一关。故事问题只会涉及故事中已展示的事件。游戏板会适应屏幕；小屏幕或放大文字时，较长内容仍可滚动查看。'],
   ['Where are my home cards?','主页卡片在哪里？','Customise my home chooses which cards appear. The navbar toggle hides or shows them. Back to games restores the selected cards.','在“定制我的主页”选择卡片，用导航栏开关显示或隐藏。“返回游戏”恢复所选卡片。'],
   ['How can I avoid getting tired?','如何避免疲劳？','Choose a short session, try an unscored practice round, pause, or replay with fresh content. Results keep Done, Replay, Next level when available, Settings and Home visible. Answer timers are optional; memory viewing time is chosen separately. Move & Remember increases memory variety and sequence length without increasing movement speed. Garden Pets has no scores, timers or care penalties.','可选择短时游戏、尝试不计分练习、暂停，或用新内容重玩。结果页直接显示完成、重玩、适用时的下一关、设置和主页。答题计时可选，记忆观看时间单独设置。“动一动 · 记一记”增加记忆变化与序列长度，不加快动作速度。花园宠物不设分数、计时或照顾惩罚。'],
   ["What do Menu, Pause, Skip and Next do?", "菜单、暂停、跳过与下一题有何不同？", "In Everyday Life and the new activity previews, ☰ opens the game menu with Resume and Leave; Pause offers Resume without leaving. Skip moves past an unanswered question without credit. Next continues after an answer or feedback. Available controls vary by activity.", "在日常生活与新活动预览中，☰打开游戏菜单，可继续或离开；暂停可继续而无需退出。跳过会略过未回答的问题，不得分；下一题用于回答或反馈后继续。各活动提供的控件可能不同。"],
   ['How do multiplayer sessions start and finish?','多人游戏如何开始和结束？','Choose a group game. Guests press Ready; the host starts a shared countdown. After each round, replay, choose another game or finish. Changing games resets readiness. Completed scores are saved.','选择小组游戏。其他玩家点击准备好了，由房主启动共同倒计时。每轮结束后可重玩、更换游戏或结束。更换游戏会重置准备状态，已完成积分会保留。'],
   ['Can I receive invitations while playing?','游戏中能收到邀请吗？','Enter the online lobby to receive available-room notices. Hosts receive an in-app join alert and optional sound. Tap I’m here to acknowledge waiting players. No device push or automatic WhatsApp messages are sent. Invite via WhatsApp opens a prepared message; choose a recipient and send it yourself.','进入在线大厅可接收可加入房间的提示。房主会收到应用内加入提示及可选提示音。点击“我在这里”回应等待玩家。不发送设备推送或自动WhatsApp消息。WhatsApp邀请会打开预填消息，由您选择收件人并发送。'],
   ['What if the host leaves?','房主离开怎么办？','Choose Keep hosting or Close room when leaving the multiplayer screen. Before play starts, new joins pause when the host disconnects. The room closes after two minutes without a host connection or acknowledgement of an arrival. A reminder appears after 30 seconds. Active games do not use this waiting-room timeout. Browser suspension may delay alerts. Saved scores remain.','离开多人游戏画面时，选择继续主持或关闭房间。游戏开始前，房主断线会暂停新玩家加入。房主断线或未回应加入玩家达两分钟，房间自动关闭；30秒后会提醒。进行中的游戏不使用此等待超时。浏览器暂停可能延迟提示。已保存成绩保留。'],

   ['How do online matching cards work?','在线配对卡片如何操作？','After the shared countdown, matching cards show for 5 seconds with 6 pairs, or 8 seconds with 10 pairs. Cards then close and matching begins. Rejoining does not restart the preview.','共同倒计时结束后，6对卡片显示5秒，10对显示8秒。随后卡片翻回并开始配对。重新进入不会重置预览。'],
   ['What does a storage warning mean?','存储警告是什么意思？','If saving fails, keep this page open and export each player’s JSON backup from Account settings → Saved data & backup → Player backup & import. Check browser storage space and permissions. An unreadable save starts a temporary garden while preserving the original data as a recovery copy. Download original data keeps that copy for repair; it may contain all local profiles and is not a player-backup JSON for importing. Keep it private. If storage is full, the original stored data is left untouched.','如果保存失败，请保持页面打开，并在账户设置 → 保存资料与备份 → 玩家备份与导入中为各玩家导出JSON备份。检查浏览器存储空间与权限。无法读取存档时，应用会启动临时花园，同时保留原始资料作为恢复副本。“下载原始资料”可保存该副本以供修复；它可能包含所有本地玩家资料，并非用于导入的玩家JSON备份，请妥善保管。存储空间不足时，不会覆盖原始存档。'],
   ['How are daily practice games chosen?','每日练习如何选择？','The app compares your last five completed results per eligible scored game and chooses the three lowest averages. Garden Pets, Today & Here, Around Us and the six new game previews are excluded. Ties favour the game played less recently. With fewer than three recorded games it fills the remaining places with other activities. Accuracy, completion and win results differ between games; this is a practice suggestion, not a diagnosis. Only the current local player’s retained results are used, not online rankings or speed.','应用比较符合条件的计分游戏最近最多五局的平均成绩，选择最低的三项。花园宠物、今日此地、身边新鲜事与六项新游戏预览不参与选择；同分时优先选择较久未玩的游戏。记录少于三项时补充其他活动。不同游戏使用正确率、完成率或胜负结果，因此仅作为练习建议，不是诊断。仅使用当前本地玩家保留的记录，不使用在线排名或速度。'],
   ['How do I return home or change a game?','如何返回主页或更换游戏？','Select the Mind Garden sprout logo at the top left to return to the welcome page. The logo stays visible on phones, tablets and desktops; its name appears when space allows. All Games opens Catalog, where the centred All Games and My Games buttons let you browse or open your selection. Categories list All Games first, followed by the other categories in English alphabetical order. Search, choose a category and select a difficulty before starting.','点击左上角的心灵花园嫩芽标志返回欢迎页。手机、平板和电脑均保留标志，空间足够时显示名称。所有游戏会打开游戏目录，居中的“所有游戏”和“我的游戏”按钮可供浏览或查看个人选择。类别以所有游戏为首，其余按英文名称字母顺序排列。可搜索、选择类别，并在开始前选择难度。'],
   ['Why can’t I hear sound?','为什么听不到声音？','Check your device volume and whether the browser tab is muted. Open Music in the navbar or ☰ menu, select a sound and press ▶. Nature sounds can be paused by games or other music; welcome videos start muted.','检查设备音量及浏览器标签页是否静音。打开导航栏或☰菜单中的音乐，选择声音并点击▶。游戏或其他音乐可能暂停自然声音；欢迎视频默认静音。'],
   ['Why is animation off?','为什么动画处于关闭状态？','The app initially follows your device’s Reduce Motion setting. Use Menu → Settings → Animation to turn movement on or off, or Garden view → Scenery & media to choose Off, Gentle or Standard; your choice is saved for this player. Video playback is separate.','应用最初遵循设备的减少动态效果设置。在菜单 → 设置 → 动画中开关动态效果，或在花园景色 → 景色与媒体中选择关、轻柔或标准，选择会保存在此玩家的设置中。视频播放另行控制。'],
   ['How do I fix text that feels too large or small?','文字太大或太小怎么办？','Use T− / T+ or select a percentage from 80% to 200% in the navbar or ☰ menu. The ↺ button resets text to exactly 100%. Game cards wrap to fit. The navbar stays on one row, and the bouquet artwork keeps its proportions while its text grows.','使用导航栏或☰菜单中的T− / T+，或选择80%至200%的百分比。↺按钮将文字重设为100%。游戏卡片会根据空间换行；导航栏保持单行，花束文字放大时，图像仍保持适当比例。'],
   ['Where are settings?','设置在哪里？','Open the labelled Menu button. It contains account, language, appearance, text size, music and motion controls.','打开标有菜单的按钮，其中包含账户、语言、外观、字号、音乐和动画控件。'],
   ['Why won’t a photo or video appear?','为什么照片或视频没有显示？','Choose the right player and light/dark scenery under Garden. Use JPEG, PNG or WebP for scenery photos, and MP4 or WebM for videos. Each player can keep up to 3 videos of up to 100 MB each. If a video cannot play, try another file; browser codec support varies.','在花园中确认当前玩家及浅色/深色背景。背景照片使用JPEG、PNG或WebP，视频使用MP4或WebM。每位玩家最多保存3个视频，每个不超过100 MB。若无法播放，请尝试其他文件；浏览器支持的视频编码可能不同。'],
   ['Why can’t I join another room?','为什么无法加入另一个房间？','Only one active room is allowed in this browser’s online session. Guests must Leave room; hosts must Finish session or Cancel game & close room before joining another. Back to garden · stay joined keeps the current room active. Online play needs an internet connection. An expired or unavailable room offers Back to lobby; completed rankings remain accessible through Saved online rankings.','此浏览器的在线会话只能参与一个活动房间。客人须退出房间；房主须结束本次游戏或取消房间，才可加入另一房间。“返回花园 · 保留参与”仍会保留当前房间。在线游戏需要网络连接。房间过期或不可用时，可选择返回大厅；已完成的排名仍可通过“已保存的在线排名”查看。'],
   ['Where are my progress and backup?','我的进度与备份在哪里？','Check that you selected the same player and browser. Signed-in accounts sync saved progress when online; local-only players stay on this device. In Account settings → Saved data & backup → Player backup & import, import a Mind Garden JSON backup, then select the imported player. Existing players are kept. CSV is for viewing and cannot be imported.','请确认选择了同一玩家并使用同一浏览器。登录账户后，已保存进度会在联网时同步；本地玩家资料仅保留在此设备。在“账户设置 → 保存资料与备份 → 玩家备份与导入”中导入心灵花园JSON备份，再选择导入的玩家。现有玩家会保留。CSV仅供查看，无法导入。'],
   ['What if the feedback form does not load?','反馈表无法加载怎么办？','Check your internet connection, open Contact and choose Open in new tab. The form’s questions are bilingual; Google controls its own buttons, notices and language. You do not need to include game history or private information to describe a problem.','检查网络连接，打开联系并选择在新标签页打开。表单问题为中英双语；Google控制其自身按钮、提示与语言。描述问题时，无须附上游戏历史或私人资料。']
  ];
  const privacy=[
   ['Singapore PDPA','新加坡个人资料保护法（PDPA）','This notice explains Mind Garden’s current data handling with reference to Singapore’s Personal Data Protection Act 2012 (PDPA), where applicable. The Act includes requirements on purposes and consent, access and correction, protection, retention and overseas transfers. Your options and the app’s current limitations are described below.','本说明参照适用的新加坡《2012年个人资料保护法》（PDPA），介绍心灵花园目前处理资料的方式。该法涵盖用途与同意、查阅与更正、保护、保留期限及跨境传输等要求。下文说明您的选择及应用目前的限制。'],
   ['Why information is used','资料的用途','Local player information saves your preferences, progress and practice recommendations. Online identifiers, room activity and scores support room membership, invitations, shared games and saved rankings. The feedback form is for suggestions, troubleshooting and privacy enquiries; submit only information needed for your request. A nickname is enough for gameplay.','本地玩家资料用于保存偏好、进度及练习建议。在线标识、房间活动与成绩用于房间参与、邀请、共同游戏及已保存的排名。反馈表用于建议、问题排查与隐私咨询；请仅提交处理请求所需的资料。游戏使用昵称即可。'],
   ['Clearer play and varied routes','清晰操作与多变路线','Games use a plain background. Back and Close sit in the header; Pause, available Hint and Settings sit below progress. Icon help appears on hover, focus or long press. Home and Back ask before leaving. Yellow bulbs provide hints. Connect the Dots uses numbered grid routes: visit checkpoints in order, avoid reusing squares, and fill the board when instructed. Hints suggest a valid continuation or an undo towards a suggested solution. Gentle dominoes automatically takes the garden friend’s turn after a short pause; pausing stops the pending turn. Hints are recorded; activities that already distinguish assisted answers retain that distinction.','游戏使用纯色背景。返回与关闭位于标题栏；暂停、可用的提示与设置位于进度下方。悬停、聚焦或长按图标显示说明；主页与返回先确认退出。黄色灯泡提供提示。顺序连点使用数字方格路线：按顺序经过检查点，不重复格子，并按要求填满棋盘。提示可建议下一步，或建议撤销以回到一条可行路线。轻松多米诺的花园伙伴稍作停顿后自动出牌，暂停会停止等待中的出牌。提示次数会被记录，原有区分辅助作答的活动继续保留该规则。'],
   ['Consistent controls and account identity','一致的控件与账户身份','Gameplay uses Back and Close in the header, with Pause, Hint and Settings below progress. Language and sound stay together above the task; the music note controls background audio. Completion offers Done, Replay and Next level when available. Settings and Home remain visible. Exit confirmation uses Keep playing and Exit. Information buttons open on tap. Account shows sign-in identity separately from saving status. An optional account photo stays on this device and is separate from player pictures.','游戏标题栏提供返回与关闭；进度下方提供暂停、提示与设置。语言和声音位于任务上方，音符控制背景声音。完成后提供完成、重玩及适用的下一关，设置与主页始终可见。退出确认使用继续游戏及退出按钮。点击信息按钮打开说明。账户将登录身份与保存状态分开显示。可选的账户照片仅存于此设备，与玩家照片分开。'],
   ['Simpler game menus','简洁游戏菜单','Games has All Games and My Games tabs, search and a category selector. Each game has one card; its information button explains the game without launching it. Choose a game to adjust its own settings. Completed levels show Done, Replay and Next level when available. Next level stays in the same game. The compact footer uses labelled controls with help on hover, keyboard focus or long press. The gear opens Settings. Settings includes Easier level and Next selected game when another game is queued. The latter starts a different game. Back returns from Options or a break to your saved result. Close returns to the games list you started from; Home returns to the welcome garden.','游戏菜单提供所有游戏与我的游戏页签、搜索及类别选择。每个游戏只有一张卡片，说明按钮会显示玩法而不启动游戏。选择游戏后可调整该游戏的设置。完成关卡后显示完成、重玩及下一关（如有）；下一关仍是同一游戏。简洁页脚提供休息图标、选项、游戏及主页图标。选项内可选择较轻松关卡；队列中还有游戏时，可选择“下一个已选游戏”开始不同的游戏。返回箭头从选项或休息画面返回已保存的成绩，关闭返回开始时的游戏列表，主页图标返回欢迎花园。'],
   ['Account setup and recovery','账户设置与恢复','The navbar shows your account name when signed in and Sign in when signed out, in every orientation. Creating account appears while the request runs. Account created confirms the server created your account; the separate Players saved confirmation means selected progress was uploaded. Password generated alone does not create an account. Local player means you are using this browser’s records. Sign in and Create account are separate screens. Open Create account from Online account (optional). After creation or password reset, save login details on their own screen, then continue to players. Create account asks for an account name and a password of at least 10 characters. Generate strong password is optional. You can optionally generate a recovery key at creation, or later from the signed-in account with your current password. Save Recovery Key to Device downloads a private file. A new key invalidates the previous key; resetting a password also replaces it. After successful creation/reset, the app offers the password to a supported browser manager. Use password manager retries this; browsers may suppress prompts. Save Password to Device downloads one unencrypted file with your account name, password and any recovery key shown. Keep it private. Save Recovery Key to Device downloads the key separately. These downloads work on computers, phones and tablets that support file downloads. Optional Device sign-in uses a passkey with Face ID, fingerprint or the device PIN when supported and configured. Set it up from Account after signing in; passwords remain available. Password recovery revokes existing passkeys, so set them up again afterwards. The recovery code appears immediately after creation and has its own PC download; it is not a device passkey. Passwords never enter player backups.','所有屏幕方向下，登录后导航栏显示账户名，退出后显示登录。提交时显示正在创建账户；账户已创建表示服务器已完成创建，玩家已保存则表示选中的进度已上传。仅生成密码并不代表已创建账户。本地玩家表示使用此浏览器的记录。登录与创建账户为独立页面。从在线账户（可选）打开创建账户。创建账户或重置密码后，请在独立页面保存登录资料，再继续选择玩家。创建账户需输入账户名及至少10个字符的密码，可选择自动生成高强度密码。可在创建时选择生成恢复密钥，也可登录后凭当前密码生成。保存恢复密钥到设备会下载私人文件；新密钥会使旧密钥失效，重置密码也会更换密钥。创建账户或重置成功后，会尝试交给支持的浏览器密码管理器，浏览器可能不弹提示。可点击使用密码管理器重试，或点击保存密码到设备，将账户名、密码及显示的恢复密钥下载到一个未加密私人文件。恢复密钥可单独下载到支持文件下载的电脑、手机或平板。设备及服务器支持时，可在登录后的账户中选择设置设备登录，使用面容识别、指纹或设备PIN；仍可使用密码。通过恢复密钥重置密码会撤销旧通行密钥，之后请重新设置。恢复代码在创建后立即显示并可单独下载到电脑，它并非设备通行密钥。玩家备份不包含密码。'],
   ['Account saving and exports','账户保存与导出','Choose Online account (optional) from Players. Sign in to load account players; device-only players stay separate. For an empty account, select players to copy or start with a new player. Save device players to this account copies selected records without removing originals. Matching names are not merged; a conflicting player ID creates a separate copy. Choose players carefully to avoid duplicates. Changes save automatically once connected; sign out to return to device-only profiles. Accounts have no separate facilitator permissions.','从玩家页面选择在线账户（可选）。登录后读取账户玩家，设备玩家单独保留。空账户可选择复制玩家或创建新玩家。将设备玩家保存至账户会复制选中的记录并保留原始资料，同名玩家不会合并；标识冲突时会创建独立副本，请避免重复复制。连接后更改会自动保存；退出登录返回设备玩家。账户没有独立的带领者权限。'],
   ['On this device','此设备上的资料','Player names, avatars, preferences, scores and retained activity are saved in this browser. Personal photos and welcome videos are also stored locally. My Life Album preview photos and labels are temporary, stay in this tab, and are discarded when you leave the activity or reload. They are not uploaded or included in backups. Personal music files must be selected again after a reload. Local-only profiles have no sign-in. Online accounts add password/passkey-protected server access. Account copies remain on this device even after sign-out and can be restored from Players → Saved account copies on this device. Anyone with access to this browser can access those local copies. Use your own device or a separate operating-system/browser profile for privacy. Players’ Progress should be used with everyone’s agreement.','玩家名称、头像、偏好、成绩与保留的活动记录保存在此浏览器。个人照片与欢迎视频也保存在本地。我的生活相册预览中的照片与标签仅暂存在当前页面，离开活动或刷新时会清除，不会上传，也不包含在备份中。刷新后需重新选择个人音乐文件。仅限本地的玩家无需登录。在线账户通过密码或通行密钥保护服务器访问。退出登录后，账户副本仍保留在设备，可从“玩家 → 此设备上的账户副本”恢复。能使用此浏览器的人也能访问本地副本，请使用个人设备或独立系统/浏览器配置保护隐私。使用玩家进度前，应取得所有人的同意。'],
   ['Online play and feedback','在线游戏与反馈','Online play sends your display name, session identifier, room activity and results to the game server. The lobby can show the host’s name and open room code. Room participants can see player names, scores and saved rankings. Opening Contact connects to Google Forms. Information you submit goes to Google and the form owner; the app does not automatically attach your player history.','在线游戏会将显示名称、会话标识、房间活动与成绩发送到游戏服务器。大厅可显示房主名称与开放房间码。房间参与者可看到玩家名称、成绩及已保存的排名。打开联系会连接Google表单。提交的资料会发送给Google及表单所有者；应用不会自动附上玩家历史。'],
   ['Service providers and overseas processing','服务提供方与跨境处理','Loading the app connects to Cloudflare hosting and may request fonts from Google. Opening Contact connects to Google Forms. These services receive connection information such as your IP address, and may process data outside Singapore depending on their services and configuration. Google manages its form cookies and service notices.','加载应用会连接Cloudflare托管服务，也可能向Google请求字体。打开联系会连接Google表单。这些服务会接收IP地址等连接信息，并可能根据其服务与配置在新加坡境外处理资料。Google自行管理其表单Cookie与服务提示。'],
   ['Your choices and privacy requests','您的选择与隐私请求','You can play local games without entering the online lobby or submitting feedback. To stop online participation, leave or close your room, then choose Go offline. For access, correction, consent withdrawal or other privacy requests, use Contact and begin your message with “Privacy / PDPA”. Provide only relevant details, such as a room code and approximate date. Requests may require identity verification and are subject to applicable legal requirements. Do not send passwords, session tokens, identity documents or full backups through the general feedback form.','无需进入在线大厅或提交反馈，也可玩本地游戏。如需停止在线参与，请退出或关闭房间，再选择退出在线大厅。如需查阅、更正、撤回同意或提出其他隐私请求，请通过联系提交，并在消息开头注明“隐私 / PDPA”。仅提供房间码、大致日期等相关资料。请求可能需要核实身份，并须遵守适用法律要求。请勿通过一般反馈表发送密码、会话令牌、身份证件或完整备份。'],
   ['How long records remain','资料保留情况','Activity and received multiplayer history are no longer automatically trimmed at 300 entries. Rename, player switching and sign-out keep device records. Previously discarded records cannot be recovered. Account requests have a 4 MB limit and compressed storage has a 1.8 MB limit; if saving fails, export the local data and keep it until resolved. Other local preferences and media remain until removed or browser storage is cleared. Waiting rooms may close earlier when the host is unavailable; all rooms expire after 24 hours. Completed rankings remain. This version has no scheduled deletion of server history and does not control retention of submitted Google Forms feedback. Use Contact to ask about server-held or feedback records.','活动及已接收的多人历史不再自动限制为300条。修改名称、切换玩家及退出账户会保留设备记录，之前已丢弃的记录无法恢复。账户请求上限为4 MB，压缩存储上限为1.8 MB；保存失败时请导出并保留本地资料，直到问题解决。其他本地偏好与媒体会保留至被删除或浏览器存储被清除。房主不可用时，等待房间可能提前关闭；所有房间24小时后过期。已完成排名保留。本版本没有服务器历史的定期删除机制，也不控制已提交Google表单反馈的保留期限。如需了解服务器或反馈记录，请通过联系咨询。'],
   ['Back up or move your data','备份或迁移资料','Account settings → Saved data & backup → Player backup & import exports the selected player’s retained history, scores and preferences as JSON. Activity histories are no longer automatically trimmed at 300 games. Account player copies are retained on this device after sign-out. Browser storage limits still apply; clearing site data removes local records. Backups exclude photos, videos, personal music, other players and online sessions. Importing creates a separate player; it does not overwrite existing players. Keep downloaded backups somewhere private.','“账户设置 → 保存资料与备份 → 玩家备份与导入”可将所选玩家保留的历史、成绩与偏好导出为JSON。本地活动不再自动限制为300局，退出账户后仍保留账户玩家副本。浏览器存储空间有限，清除网站数据会移除本地记录。备份不包含照片、视频、个人音乐、其他玩家及在线会话。导入会创建独立玩家，不会覆盖现有玩家。请妥善保管下载的备份。'],
   ['Remove local data','删除本地资料','Back up anything you want to keep first. Remove personal scenery photos and welcome videos under Garden → Scenery & media before removing their player. Use the trash icon on a player card to remove that player. History controls apply to the current player. Type its name to confirm; connected accounts also ask for the account password. Other players’ controls stay hidden. Shared device-only profiles cannot verify who is using the browser. Separate device copies and downloaded backups remain. To erase all players and local media, clear this site’s stored data in your browser; this cannot be undone without backups and original media files. Downloaded backups remain until you delete those files yourself.','请先备份需要保留的资料。删除玩家前，先在花园 → 景色与媒体中移除其个人背景照片与欢迎视频。使用玩家卡片上的垃圾桶图标删除该玩家；记录控件仅用于当前玩家。须输入玩家名确认，已连接账户还须输入账户密码。其他玩家的删除控件会隐藏。共用设备的本地玩家无法验证实际操作者，独立设备副本与已下载的备份会保留。如需清除所有玩家与本地媒体，请在浏览器中清除此网站的存储数据；没有备份与原始媒体文件时无法恢复。已下载的备份须自行删除。'],
   ['Limits of local removal','本地删除的范围','Removing a local player, leaving a room or clearing browser storage does not erase server-held room records or feedback already submitted to Google Forms. This app does not currently offer automatic deletion of those remote records. Use Contact for questions about them.','删除本地玩家、退出房间或清除浏览器存储，不会删除服务器上的房间记录或已提交至Google表单的反馈。应用目前不提供这些远程记录的自动删除功能。如有疑问，请通过联系反馈。']
  ];
  const button=(action,en,zh)=>'<button type="button" class="btn" data-about-action="'+action+'">'+T(en,zh)+'</button>';
  const entries=items=>items.map(x=>'<details><summary>'+T(x[0],x[1])+'</summary><div class="about-answer"><p>'+T(x[2],x[3])+'</p></div></details>').join('');
  return '<nav class="about-shortcuts" aria-label="'+T('About sections','关于栏目')+'">'+[['aboutSetup','First-time setup','首次使用设置'],['aboutFAQ','Help & troubleshooting','帮助与问题解答'],['aboutPrivacy','Privacy, PDPA & my data','隐私、PDPA与我的资料'],['aboutUserGuide','User guide','使用指南']].map(x=>'<button type="button" class="btn" data-about-target="'+x[0]+'">'+T(x[1],x[2])+'</button>').join('')+'</nav><div class="about-support">'+
   '<details id="aboutSetup"><summary>'+T('First-time setup','首次使用设置')+'</summary><div class="about-answer"><p>'+T('All steps are optional.','所有步骤均可跳过。')+'</p><ol>'+setup.map(x=>'<li><strong>'+T(x[0],x[1])+'</strong><p>'+T(x[2],x[3])+'</p></li>').join('')+'</ol><div class="about-actions">'+button('players','Choose or add a player','选择或添加玩家')+button('settings','Open settings','打开设置')+button('daily','Today’s Games','今日游戏')+'</div></div></details>'+
   '<details id="aboutFAQ"><summary>'+T('FAQ · Help & troubleshooting','常见问题 · 帮助与问题解答')+'</summary><div class="about-answer about-questions">'+entries(faq)+'<div class="about-actions">'+button('settings','Open settings','打开设置')+button('contact','Contact & feedback','联系与反馈')+'</div></div></details>'+
   '<details id="aboutPrivacy"><summary>'+T('Privacy, PDPA & my data','隐私、PDPA与我的资料')+'</summary><div class="about-answer about-questions"><p class="privacy-updated">'+T('Privacy notice updated: 14 November 2026.','隐私说明更新于2026年11月14日。')+'</p>'+entries(privacy)+'<p><a href="https://sso.agc.gov.sg/Act/PDPA2012" target="_blank" rel="noopener noreferrer">'+T('Read Singapore’s PDPA on Singapore Statutes Online ↗','在新加坡法令在线阅读PDPA原文 ↗')+'</a></p><div class="about-actions">'+button('data','Backup and data settings','备份与资料设置')+button('players','Manage local players','管理本地玩家')+button('contact','Privacy enquiry / request','隐私咨询 / 请求')+'</div></div></details></div>';
 }
 function aboutContent(release){
 const sections=[
 ['Latest improvements','最新改进',[
 ['Version 6.3: a host can open a group to everyone, and open groups appear under Open groups in Play Together. Private stays the default. The group game list uses the same pictures as All Games, panels keep a steady size, and the top bar stays in view. Before starting, the host is told who is away; a chime and “Round 2 is starting” call everyone back.','第6.3版：主持人可以把小组向所有人开放，公开小组会显示在“一起玩”的“公开小组”中，默认仍为私人小组。小组游戏列表使用与“所有游戏”相同的图片，窗口大小保持稳定，顶部栏始终可见。开始前会提示谁暂时离开；提示音和“第 2 轮即将开始”会提醒大家回来。'],
 ['Version 6.2.1 makes text easier to read: paragraphs stay together and turn left-aligned when they run onto a second line. It also removes a sideways scrollbar in the group waiting room and keeps the game list the same size while you search.','第6.2.1版让文字更易阅读：段落保持完整，换行时改为左对齐。同时移除了小组等待室的横向滚动条，搜索游戏时列表大小保持不变。'],
 ['Version 6.2 redesigns Play Together. The first screen explains it and offers Start a group or Join a group, with no separate lobby to enter. Hosts see the group code and Send on WhatsApp straight away. Everyone sees who is Ready, how to play before starting, and a results table with the round winner, round scores and totals.','第6.2版重新设计了“一起玩”。首页说明玩法，并提供“开始小组”和“加入小组”，无需另外进入大厅。主持人会立即看到小组码和“用WhatsApp发送”。每个人都能看到谁已准备、开始前的玩法说明，以及显示本轮赢家、本轮得分和总分的结果表。'],
 ['Version 6.1 makes Play Together private. Only people you give the group code or invite link to can join, and new groups are no longer announced to everyone online. A group no longer closes because the host did not tap after someone joined. Guests who are away sit out the round instead of blocking Start, and the host can remove a guest before the game starts. If the host is away, guests see how long until the group closes and can leave. After 10 minutes away the group closes and scores are kept.','第6.1版让“一起玩”成为私人小组。只有获得小组码或邀请链接的人才能加入，新小组不再向所有在线玩家公告。有人加入后，主持人未点击屏幕也不会导致小组关闭。暂时离开的玩家本轮不参加，不再阻挡开始；开始前主持人可移出玩家。主持人离开时，其他玩家会看到小组还有多久关闭，并可随时退出。主持人离开10分钟后小组关闭，积分会保留。'],
 ['Version 6 aligns game controls and review counters. Startup uses your selected background without the old illustration.','第6版统一游戏控件与回顾计数。启动时使用已选背景，不再闪现旧插画。'],
 ['Game headers keep Back and Close visible. Language and sound controls are centred. Questions sit with their sequences, hints use larger text, and expanded menu groups scroll into view. Number Patterns hints explain the rule before showing a calculation. Matching Pairs shows its rule before Begin and the remaining hints. Pets show a still heart with reduced motion.','游戏顶部保留返回与关闭按钮，语言与声音按钮居中。问题紧邻数列，提示文字放大，展开的菜单自动滚入视野。数字规律提示先说明规律，再显示计算步骤。配对游戏在开始前说明规则，并显示剩余提示次数。减少动态时，宠物显示静止爱心。'],
 ['Matching cards resize within their play area without overlapping. Single reference pictures and their picture answers use matching square tiles. Desktop and tablet layouts use available height, compact dense boards, and keep detailed puzzle rules in expandable help. Language and sound controls are available directly above gameplay; Change level is in Settings. My Progress shows ten history entries per page in a taller panel. Number answers appear side by side, wrapping into multiple columns on narrow screens. Long word labels wrap within their buttons; picture grids reserve room for their answers. On desktop, larger dot, link and picture boards sit beside their instructions.','配对卡片按游戏区域调整大小，避免重叠。单张题目图片与图片答案使用相同大小的正方形卡片。桌面和平板布局充分使用可用高度，密集棋盘更紧凑，详细解题规则可按需展开。语言和声音控制位于游戏上方；更改关卡位于设置内。我的进度使用更高的面板，每页显示十条记录。数字答案横向并排显示，在窄屏上以多列排列。较长的文字标签在按钮内换行；图片网格为答案预留空间。桌面上的大型路径、连线与拼图棋盘与说明并排显示。'],
 ['Leaderboard shows up to ten players per page in a taller panel. Smaller screens scroll the results. Saved online rankings has more space between rows and help icons to the right of their labels.','排行榜使用更高面板，每页最多显示十位玩家；小屏幕可滚动查看成绩。已保存的在线排名增加行间距，说明图标位于标签右侧。'],
 ['My Games shares the All Games card grid, search and category filter. The page grows with your selection. Add games opens a selection picker; remove with − or restore with Undo. Play my selection starts your saved games in order.','我的游戏与所有游戏共用卡片网格、搜索及类别筛选。页面随已选游戏数量扩展。添加游戏可打开选择菜单；点击−移除，或撤销以恢复。按顺序开始可依次游玩已选游戏。'],
 ['Group play adds join alerts and manual WhatsApp invitations. Hosts can keep hosting or close the group.','一起玩新增加入提示及手动WhatsApp邀请。主持人可继续主持或关闭小组。'],
 ['Play Together: choose Start a group, pick a game, then choose who can join: only people you invite (the default) or anyone using Mind Garden. Invite people with the code or Send on WhatsApp. Others choose Join a group and type the 6-character code, tap your link, or join from Open groups. The host starts every round and everyone starts together.','一起玩：选择“开始小组”并挑选游戏，然后选择谁可以加入：只有你邀请的人（默认）或任何心灵花园用户。用小组码或“用WhatsApp发送”邀请别人。其他人选择“加入小组”并输入6位小组码、点击你的链接，或从“公开小组”加入。每一轮都由主持人开始，大家同时开始。'],
 ['Short story answers stack in one column on narrow screens, keeping labels readable and controls visible.','窄屏上的短篇故事答案按单列排列，保持文字清晰，控制按钮始终可见。'],
 ['Desktop games use a centred container with balanced text, answer spacing and consistent control icons. Long activities scroll inside the play area while footer controls remain visible. Distant birds use smaller silhouettes and scene-specific clear-sky flight paths; birds are hidden for personal photos and videos.','桌面游戏采用居中容器，均衡安排文字、答案间距及控制图标。较长内容在游戏区域内滚动，底部控件保持可见。远处鸟儿体型更小，并沿各景色的无遮挡天空路线飞行；个人照片与视频中隐藏鸟儿。'],
 ['Detailed birds and butterflies replace emoji wildlife. Birds alternate wingbeats with gliding; butterflies follow drifting paths. Gentle reduces travel and numbers; Off hides wildlife. Animation pauses during games, menus and hidden tabs.','细致的鸟类与蝴蝶取代表情图案。鸟儿交替振翅与滑翔，蝴蝶沿缓慢曲线飞行。轻柔模式减少数量与移动速度；关闭模式隐藏动物。游戏、菜单及后台标签页中动画暂停。'],
 ['Choose from 22 paired day/dusk sceneries, including restored gardens and neutral architectural scenes with plain roof details. Scenery keeps its source colours and contrast without a shared sepia filter. Subtle sky texture reduces visible sunset banding without blurring the image.','可选择22组日间与黄昏景色，包括恢复的花园与采用素雅屋顶细节的中性建筑背景。景色保留原图的色彩与对比度，不再统一套用棕褐色滤镜。细微的天空纹理减轻日落色带观感，不会模糊图片。'],
 ['My Progress and Leaderboard use game, difficulty and period filters, charts and paginated records. Scores are game results, not health measures. Arithmetic symbols and card icons use readable gold, orange, rose and sage tones.','我的进度与排行榜提供游戏、难度、时段筛选、图表及分页记录。分数反映游戏表现，不代表健康状况。运算符号与卡片图标采用清晰的金色、橙色、玫瑰色和鼠尾草绿。'],
 ['During group play, the header closes or leaves the group. Keep hosting preserves the same screen. Language and sound controls are centred. Scores appear after the round.','小组游戏的标题栏可关闭或退出小组。继续主持会保留当前画面，语言与声音按钮居中，回合结束后显示积分。'],
 ['Shorter English and Chinese descriptions; centred submenus. Back to games restores cards hidden by the navbar toggle.','精简中英文说明、居中子菜单。“返回游戏”恢复被导航栏隐藏的卡片。'],
 ['Today’s Games is the main welcome action. All welcome cards can be hidden in Customise my home. Enjoy the garden fills the view with scenery, with progress below and Back to games to restore your cards.','今日游戏是欢迎页的主要操作。定制我的主页可隐藏任意欢迎卡片。欣赏花园以整屏展示景色，进度保留在下方；返回游戏可恢复卡片。'],
 ['Groups hold up to eight players. The game catalogue has search, categories and supported game options. Join alerts show player names. Return to a joined group from Play Together.','每组最多八人。游戏目录提供搜索、类别与支持的游戏选项。加入提示显示玩家名称，可从一起玩返回已加入的小组。'],
 ['Confirmed account-player deletion also removes the matching saved device copy. Saved on this device offers separate restore and delete actions. Completed bouquets stay in My Garden. At Full Bloom, Grow another starts a fresh bouquet without changing scores. Back returns one menu step. Confirmation appears only if unsaved gameplay would be lost. All Games and My Games share the same expanding card grid. Tap the information icon for details. Each preparation screen shows its instruction once. The Play menu uses two columns when space permits and stacks at larger text sizes. The slimmer navigation grows with text size. Restored and newer scenery choices are available together. All Games has search and a compact category dropdown. Use − to remove a selected game; Undo restores it without changing scores.','确认删除账户玩家后，也会删除此设备上对应的保存副本。已保存在此设备提供独立的恢复与删除操作。完成的花束保留在我的花园。盛开后，选择再种一束即可开始新花束，成绩不变。返回箭头返回上一级菜单；只有未保存的游戏会丢失时才需确认。所有游戏和我的游戏使用相同的自适应卡片网格。点击信息图标查看详情。每个准备画面仅显示一次玩法说明。游戏菜单在空间足够时使用两列，字号较大时改为单列。精简导航栏随字号扩大。恢复的旧景色与较新的景色可同时选用。所有游戏提供搜索和紧凑的类别下拉列表。点击−移除已选游戏；撤销可恢复游戏，成绩不变。'],
 ['Today’s Games opens one preparation screen. Review your saved level, open Options if needed, then press Begin.','今日游戏打开一个准备页面。查看已保存的关卡，按需打开选项，然后点击开始。'],
 ['The menu uses aligned icons and compact sound and animation switches. Player cards have rename and delete icons. Back and Close stay in the header; Pause, Hint and Settings share a centred row below progress. Exit confirmation uses Keep playing and Exit. Information buttons open a centred dialog. Enlarged text wraps and scrolls; the optional tagline is hidden at 150% and above.','菜单采用对齐图标和紧凑的声音及动画开关。玩家卡片提供改名和删除图标。返回与关闭位于标题栏，暂停、提示与设置在进度下方居中排列。退出确认提供继续游戏与退出按钮。说明按钮打开居中对话框。放大文字后可自动换行和滚动；150%及以上时隐藏可选标语。']]],
 ['User guide','使用指南',[
 ['First visit: choose Play today’s games or Browse all games. No online account is required for local solo play.','首次使用：选择开始今日游戏或浏览所有游戏。本地单人游戏无需在线账户。'],
 ['Game setup: Begin uses the displayed saved settings. Options contains the level, challenge and timing controls. Some activities have their own preparation controls.','游戏设置：开始使用显示的已保存设置。选项包含关卡、挑战和计时控件。部分活动有独立的准备控件。'],
 ['My Games: add games with + on All Games cards. Search or filter either collection by category. Use − to remove a favourite; Undo restores it. Scores stay unchanged. Play my selection starts all saved games, including those hidden by a search.','我的游戏：点击所有游戏卡片上的＋添加游戏。两个列表均可搜索或按类别筛选。点击−移除收藏；撤销可恢复，成绩不变。按顺序开始会游玩全部已选游戏，包括被搜索条件隐藏的游戏。'],
 ['Gameplay: Next round keeps feedback visible until you are ready. Next level starts only when selected. Change level pauses play; Cancel keeps the current round. On touchscreens, tap information icons or hold an action icon briefly for its label. Garden Pets sound starts on a deliberate stroke when Game sounds is on.','游戏：点击下一轮后才继续，方便阅读反馈。选择下一关后才开始新关卡。更改关卡会暂停游戏；取消保留当前一轮。触屏设备可点击信息图标，或短暂按住操作图标查看名称。开启游戏音效后，主动抚摸宠物会启用宠物声音。'],
 ['Players: rename keeps the same profile and history. Switch Player selects another person; adding a new player starts empty.','玩家：修改名称保留原资料与历史。切换玩家选择其他人；新玩家从空白记录开始。'],
 ['During play: Home asks before leaving; Pause stops the round. Settings pauses solo play. Completed levels offer Replay and, when available, Next level.','游戏中：主页在离开前询问；暂停可停止本局。设置会暂停单人游戏。完成后可重玩，并在适用时进入下一关。'],
 ['Play Together needs a configured server. Guests tap Ready before the host starts; a guest who is away sits out that round. The host can remove a guest before starting. Guests can leave at any time. If the host is away for 10 minutes, the group closes and scores are kept. Older rooms retain their Begin controls until closed.','一起玩需要已配置的服务器。其他玩家点击“准备好了”后由主持人开始；暂时离开的玩家本轮不参加。开始前主持人可移出玩家，其他玩家可随时退出。主持人离开10分钟后小组关闭，积分会保留。旧房间关闭前仍保留原有开始按钮。']]],
 ['Privacy and my data','隐私与我的资料',[
 ['Local profiles and account copies remain in this browser after sign-out. Other people using the same browser may access them. Keep a backup before clearing browser storage or moving devices.','本地资料及账户副本在退出后仍保留于此浏览器。使用同一浏览器的人可能访问这些资料。清除存储或更换设备前请备份。'],
 ['An online account is optional and stores only the players you explicitly choose to copy. Player identity uses separate IDs, not names. Credentials are excluded from player backups.','在线账户为可选功能，仅存储您明确选择复制的玩家。玩家使用独立编号识别，不按名称合并。玩家备份不含登录凭据。'],
 ['Personal photos, videos and music do not automatically transfer to another device. Browser storage can be cleared or evicted; it is not a permanent backup.','个人照片、视频和音乐不会自动传至其他设备。浏览器存储可能被清除，不能作为永久备份。'],
 ['Use Contact for privacy and Singapore PDPA enquiries. Do not include passwords, recovery keys or sensitive personal records in feedback.','隐私及新加坡PDPA相关咨询请使用联系功能。反馈中请勿包含密码、恢复密钥或敏感个人记录。']]]
 ];
 return '<h3 class="about-version">'+T('Version ','版本 ')+esc(release)+'</h3><p class="about-intro">'+T('Thinking games and a relaxing garden. Not a medical test or treatment.','益智游戏与休闲花园。不用于医学检测或治疗。')+'</p>'+sections.map(([en,zh,rows])=>'<details class="simple-menu-group" open><summary>'+T(en,zh)+'</summary><ul>'+rows.map(([a,b])=>'<li>'+T(a,b)+'</li>').join('')+'</ul></details>').join('')+aboutExtras()+'<p class="about-copyright">© '+new Date().getFullYear()+' Pebblebrooks. '+T('All rights reserved.','保留所有权利。')+'</p><p class="about-artwork">'+T('Artwork credits and licences:','素材署名与许可：')+'<br><a href="flags/LICENSE.txt">flag-icons · MIT</a>; <a href="https://creativecommons.org/licenses/by/4.0/">Twemoji · CC BY 4.0</a>.</p>';
 }
 function openInfo(kind){
 window.MindGardenMenuHistory?.enter('info:'+kind,()=>openInfo(kind));
  const about=kind==='about',release=document.querySelector('meta[name="mind-garden-release"]')?.content||'',title=about?T('About Mind Garden','关于心灵花园'):T('Contact & feedback','联系与反馈'),url=feedbackURL(),embed=feedbackURL(true);
  const content=about?aboutContent(release):''+(url?'<div class="feedback-actions"><a id="googleFeedbackLink" class="btn" href="'+esc(url)+'" target="_blank" rel="noopener noreferrer">'+T('Open in new tab ↗','在新标签页打开 ↗')+'</a><span>'+T('If Google asks you to sign in or the form does not load, open it in a new tab.','如果Google要求登录或表单未能加载，请在新标签页打开。')+'</span></div>':'')+(embed?'<img class="feedback-banner" src="feedback-banner.jpg" alt="" width="1200" height="300"><iframe id="googleFeedbackFrame" class="feedback-frame" src="'+esc(embed)+'" title="'+T('Mind Garden Google feedback form','心灵花园Google反馈表')+'" loading="eager" referrerpolicy="strict-origin-when-cross-origin"></iframe>':'<p id="feedbackPending" role="status">'+T('The feedback form link will be available here soon.','反馈表链接即将在此提供。')+'</p>');
  overlay('<section class="app-info '+(about?'app-info-about':'app-info-contact')+'" role="dialog" aria-modal="true" aria-labelledby="appInfoTitle" tabindex="-1"><header><h2 id="appInfoTitle">'+title+'</h2><button type="button" class="btn" id="infoClose" aria-label="'+T('Close','关闭')+'">×</button></header>'+content+'<button type="button" class="btn" id="infoDone">'+T('Done','完成')+'</button></section>');
  const panel=document.querySelector('#box .app-info'),close=()=>{closeOv();const source=document.querySelector('#unifiedNav .nav-actions [data-go="'+kind+'"]')||document.getElementById('navMore');(source?.dataset.navHidden==='true'?document.getElementById('navMore'):source)?.focus()};document.getElementById('infoClose').onclick=close;document.getElementById('infoDone').onclick=close;
  panel.querySelectorAll('[data-about-target]').forEach(button=>button.onclick=()=>{const target=document.getElementById(button.dataset.aboutTarget);if(!target)return;if(target.tagName==='DETAILS')target.open=true;const focus=target.querySelector('summary')||target;if(focus.tagName!=='SUMMARY')focus.tabIndex=-1;const box=document.getElementById('box');box.scrollTop+=target.getBoundingClientRect().top-(document.querySelector('#box .menu-exit-bar')||panel.querySelector('header')).getBoundingClientRect().bottom-16;focus.focus({preventScroll:true})});
  panel.querySelectorAll('[data-about-action]').forEach(button=>button.onclick=()=>{const action=button.dataset.aboutAction;if(action==='daily')closeOv();if(action==='data')window.MindGardenMenus.player();else if(action==='players')window.openPl();else if(action==='settings')window.openSet();else if(action==='daily')startDaily();else if(action==='contact')openInfo('contact')});
  panel.onkeydown=e=>{if(e.key==='Escape'){e.preventDefault();e.stopPropagation();close()}if(e.key==='Tab'){const buttons=[...document.getElementById('box').querySelectorAll('button,a[href],summary,iframe')].filter(el=>!el.disabled&&el.tabIndex>=0&&el.getClientRects().length),first=buttons[0],last=buttons.at(-1);if(e.shiftKey&&(document.activeElement===first||document.activeElement===panel)){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}};panel.focus();
 }
 function menuGroup(en,zh,items){return '<section class="nav-group"><h3>'+T(en,zh)+'</h3><div>'+items.map(v=>'<button data-go="'+v[0]+'"><span aria-hidden="true">'+icon(({daily:'bloom',mygames:'games',library:'grid',online:'together',progress:'progress',leaderboard:'trophy',language:'language',music:'music',account:'person',profile:'person',nature:'sound',motion:'butterfly',settings:'options',family:'together',about:'progress',quickguide:'games',contact:'person'})[v[0]]||'sprout')+'</span><span>'+T(v[2],v[3])+'</span></button>').join('')+'</div></section>'}
 let nextHelp=0;
 function info(en,zh){const id="garden-help-"+(++nextHelp);return '<div class="mg-help"><button type="button" class="mg-help-trigger" aria-label="'+T('More information','更多信息')+'" aria-expanded="false" aria-describedby="'+id+'">ⓘ</button><div id="'+id+'" class="mg-help-text" role="tooltip">'+T(en,zh)+'</div></div>'}
 function buildNav(){
  const previous=document.getElementById('navMenu');
  const menuState=previous&&!previous.classList.contains('hidden')?{
   scroll:previous.scrollTop,
   groups:[...previous.querySelectorAll('details')].filter(d=>d.open).map(d=>d.id?'#'+d.id:d.dataset.menuGroup?'[data-menu-group="'+d.dataset.menuGroup+'"]':d.classList.contains('nav-preferences')?'.nav-preferences':null).filter(Boolean),
   focus:previous.contains(document.activeElement)?document.activeElement:null
  }:null;

  const links=[['daily','✿','Today’s Games','今日游戏'],['mygames','♡','My Games','我的游戏'],['library','▦','All Games','所有游戏'],['online','♧','Play Together','一起玩'],['progress','▥','My Progress','我的进度'],['leaderboard','♜','Leaderboard','排行榜']];
  nav.innerHTML='<button class="nav-brand" data-go="home" aria-label="'+T('Mind Garden home','心灵花园主页')+'"><span aria-hidden="true">'+icon('sprout')+'</span> <span>Mind Garden</span></button><div class="nav-items">'+links.map(v=>'<button class="nav-link'+((page==='dashboard'&&v[0]==='home'||page==='library'&&v[0]==='library')?' current':'')+'" data-go="'+v[0]+'"'+((page==='dashboard'&&v[0]==='home'||page==='library'&&v[0]==='library')?' aria-current="page"':'')+' aria-label="'+T(v[2],v[3])+'"><span aria-hidden="true">'+icon(({daily:'bloom',mygames:'games',home:'home',library:'grid',online:'together',progress:'progress',leaderboard:'trophy'})[v[0]])+'</span>'+ (v[0]==='home'?'':' <span class="nav-label">'+T(v[2],v[3])+'</span>')+'</button>').join('')+
  '</div><div class="nav-actions"><button type="button" id="navAccount" class="nav-quiet nav-account" data-go="account">'+esc(window.MindGardenAccount?.navLabel()||T('Sign in','登录'))+'</button><button class="nav-quiet nav-symbol" data-go="music" aria-label="'+T('Music','音乐')+'">'+icon('music')+'</button><button class="nav-quiet nav-symbol" data-go="language" aria-label="'+T('Language','语言')+'">'+icon('language')+'</button><button type="button" id="navAppearance" class="nav-quiet nav-symbol nav-appearance" data-go="appearance"></button><button type="button" id="navMore" class="nav-more" aria-controls="navMenu" aria-expanded="false" aria-label="'+T('Open menu','打开菜单')+'">'+icon('menu')+'<span>'+T('Menu','菜单')+'</span></button></div><div id="navMenu" class="nav-menu hidden">'+menuGroup('Play','游戏',[['daily','✿','Today’s Games','今日游戏'],['mygames','♡','My Games','我的游戏'],['library','▦','All Games','所有游戏'],['online','♧','Play Together','一起玩'],['progress','▥','My Progress','我的进度'],['leaderboard','♜','Leaderboard','排行榜']])+menuGroup('Player','玩家',[['account','♙','Sign in / Account','登录 / 账户'],['family','♡','Players’ Progress','玩家进度'],['profile','♙','Switch Player','切换玩家']])+'<details class="nav-preferences"><summary>'+T('Preferences','偏好设置')+'</summary>'+menuGroup('Controls','控件',[['music','♫','Music','音乐'],['nature','◖','Background audio','背景声音'],['motion','Ⅱ','Animation','动画'],['language','文','English / 中文','English / 中文'],['settings','⚙','More settings','更多设置']])+'<fieldset class="nav-theme"><legend>'+T('Display mode','显示模式')+'</legend><div class="nav-theme-options">'+[['light',T('Light','浅色')],['dark',T('Dark','深色')],['auto',T('Auto','自动')]].map(v=>'<button type="button" data-mode="'+v[0]+'" aria-pressed="'+((save.mode||'auto')===v[0])+'">'+v[1]+'</button>').join('')+'</div></fieldset></details>'+menuGroup('Help','帮助',[['quickguide','?','Quick guide','快速指南'],['about','ⓘ','About','关于'],['contact','✉','Contact','联系']])+'</div>';
  syncAppearance();window.MindGardenAccount?.refreshUI();
  nav.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>{if(!['nature','motion','appearance'].includes(b.dataset.go))closeNavMenu();navAction(b.dataset.go)});
  const more=document.getElementById('navMore'),menu=document.getElementById('navMenu');more.onclick=()=>{const isOpen=!menu.classList.toggle('hidden');more.setAttribute('aria-controls','navMenu');more.setAttribute('aria-expanded',String(isOpen));more.setAttribute('aria-label',isOpen?T('Close menu','关闭菜单'):T('Open menu','打开菜单'));if(isOpen)menu.querySelector('button')?.focus()};
  menu.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{save.mode=b.dataset.mode;persist();applyPrefs();buildNav()});
  if(menuState){
   menu.classList.remove('hidden');more.setAttribute('aria-expanded','true');more.setAttribute('aria-label',T('Close menu','关闭菜单'));
   // Other menu modules remount their controls in mutation observers.
   queueMicrotask(()=>{
    if(document.getElementById('navMenu')!==menu)return;
    menuState.groups.forEach(selector=>{const group=menu.querySelector(selector);if(group)group.open=true});
    const f=menuState.focus;
    const target=f?.id?document.getElementById(f.id):f?.dataset.go?menu.querySelector('[data-go="'+f.dataset.go+'"]'):f?.dataset.mode?menu.querySelector('[data-mode="'+f.dataset.mode+'"]'):null;
    target?.focus({preventScroll:true});menu.scrollTop=menuState.scroll;
   });
  }

 }

 const days=()=>{const t=new Date(today()+'T12:00:00').getTime()/86400000|0;return [['shopping','rem','miss','story'][Math.abs(t)%4],['visual','find','diff','count'][Math.abs(t)%4],['calendar','routine','related','same'][Math.abs(t)%4]]};
 function renderWelcome(){
  const p=me();
  dash.innerHTML='<div class="welcome-scene"><span class="scenery-gradient-grain" aria-hidden="true"></span><div class="welcome-heading"><h1><span aria-hidden="true">'+icon('sprout')+'</span> Mind Garden</h1><p>'+T('Keep your mind active','让思维保持活跃')+'</p></div><button class="welcome-name" id="welcomeName"><span class="welcome-greeting">'+T('Welcome, ','欢迎，')+'</span><span translate="no">'+esc(p.name)+'</span> <span aria-hidden="true">✎</span></button>'+
  '<div class="welcome-ctas"><h2 class="welcome-group-title">'+T('Choose your games','选择您的游戏')+'</h2><div class="welcome-choice"><button class="welcome-feature feature-today" id="dashStart"><span class="feature-icon" aria-hidden="true">'+icon('bloom')+'</span><strong>'+T('Today’s Games','今日游戏')+'</strong></button>'+info('Three games selected for you. Take your time and play at your own pace.','为您选择三项游戏。慢慢来，按自己的节奏游玩。')+'</div>'+
  '<div class="welcome-choice"><button class="welcome-feature feature-games" id="dashBrowse"><span class="feature-icon" aria-hidden="true">'+icon('games')+'</span><strong>'+T('All Games','所有游戏')+'</strong></button>'+info('Explore every activity and choose a difficulty before you begin.','浏览所有活动，开始前选择难度。')+'</div>'+
  '<h2 class="welcome-group-title">'+T('Connect and track progress','互动与进度')+'</h2><div class="welcome-choice"><button class="welcome-feature feature-together" id="dashTogether"><span class="feature-icon" aria-hidden="true">'+icon('together')+'</span><strong>'+T('Play Together','一起玩')+'</strong></button>'+info('Invite family or friends. Get ready, then start together.','邀请家人或朋友。准备好后一起开始。')+'</div>'+
  [['dashProgress','progress','My Progress','我的进度','See your activity, scores and garden growth.','查看您的活动、成绩和花园成长。'],['dashLeaders','trophy','Leaderboard','排行榜','See rankings and compare game scores.','查看排名并比较游戏成绩。']].map(v=>'<div class="welcome-choice"><button class="welcome-feature" id="'+v[0]+'"><span class="feature-icon" aria-hidden="true">'+icon(v[1])+'</span><strong>'+T(v[2],v[3])+'</strong></button>'+info(v[4],v[5])+'</div>').join('')+'</div><div class="garden-breathing-space" aria-hidden="true"></div></div><p class="dash-disclaimer">'+T('For enjoyment and cognitive engagement. Not a medical test or treatment.','用于娱乐和认知活动，并非医疗测试或治疗。')+'</p>';
  document.getElementById('welcomeName').onclick=()=>window.MindGardenIdentity?.open();
  document.getElementById('dashStart').onclick=startDaily;
  document.getElementById('dashBrowse').onclick=()=>openLibrary();
  document.getElementById('dashTogether').onclick=()=>navAction('online');
  document.getElementById('dashProgress').onclick=()=>navAction('progress');
  document.getElementById('dashLeaders').onclick=()=>navAction('leaderboard');
 }

 const prettyCat=c=>T(...(LABELS[c]||LABELS.all));
 function gameCard(k){const m=MG[k],cat=META[k]||'logic',lvl=(me().levels||{})[k]||1,minutes=GAME_TIME[k]||3;
  return '<button class="game-tile" data-game="'+esc(k)+'" data-category="'+cat+'" aria-label="'+esc(m.n)+'"><span class="game-art" aria-hidden="true">'+gamePicture(m.ic)+'</span><span class="game-info"><strong>'+esc(m.n)+'</strong><span class="game-desc">'+esc(m.d)+'</span><span class="game-meta">'+(window.MindGardenCommercial?.has(k)?'':prettyCat(cat)+' · '+minutes+' '+T('min','分钟')+' · ')+(window.MindGardenCommercial?.has(k)?T('Practice preview · scores by level','练习预览 · 按难度保存成绩'):k==='pets'?T('Relaxed play · no scores','轻松互动 · 不计分'):(window.MindGardenActivities?.has(k)||window.MindGardenNewGames?.has(k))?T('3 relaxed choices','3种轻松难度'):T('Level '+lvl+' / 15','第 '+lvl+' / 15 关'))+'</span></span><span class="game-play" aria-hidden="true">▶</span></button>'}
 function openLibrary(kind='all'){collection=kind;filter='all';search='';switchPage('library')}
 function catalogueTile(id){
  const name=id==='pairs'?T('Matching Pairs','配对游戏'):MG[id].n;
  return id==='pairs'?'<button class="game-tile" data-game="pairs"><span class="game-art" aria-hidden="true">'+gamePicture('🌺')+'</span><span class="game-info"><strong>'+name+'</strong><span class="game-desc">'+T('Find the matching picture cards.','找出相同的图片卡片。')+'</span></span><span class="game-play" aria-hidden="true">▶</span></button>':gameCard(id).replace(/<span class="game-meta">[\s\S]*?<\/span>/,'');
 }
 function catalogueCard(id,selected){
  const personal=window.MindGardenPersonal,name=id==='pairs'?T('Matching Pairs','配对游戏'):MG[id].n,card=catalogueTile(id);
  return '<article class="personal-game-card catalogue-card">'+card+'<div class="catalogue-card-tools">'+(personal?.info(id)||'')+'<button class="btn catalogue-save" data-save-game="'+id+'" aria-label="'+esc((collection==='my'?T('Remove ','移除 '):selected?T('Added: ','已添加：'):T('Add to My Games: ','添加到我的游戏：'))+name)+'"'+(collection==='all'&&selected?' disabled':'')+'>'+(collection==='my'?'<svg viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="9"/><path d="M7 12h10"/></svg>':selected?'✓':'+')+'</button></div></article>';
 }
 function addGames(){
  const owner=save.cp,pending=new Set(),selected=new Set(window.MindGardenPersonal.config().games);
  const available=['pairs',...Object.keys(MG)].filter(id=>!selected.has(id));
  window.MindGardenMenuHistory?.enter('add-games',addGames);
  overlay('<h2>'+T('Add games to My Games','添加游戏到我的游戏')+'</h2><section id="addGamesPicker"><button id="addGamesBack" class="btn" data-menu-back hidden>'+T('Back to My Games','返回我的游戏')+'</button><div class="game-picker-filters"><label>'+T('Search games','搜索游戏')+'<input id="addGamesSearch" type="search" placeholder="'+T('Search games…','搜索游戏…')+'"></label><label>'+T('Category','类别')+'<select id="addGamesCategory"><option value="all">'+T('All categories','所有类别')+'</option>'+window.MindGardenDashboard.categories().map(([id,label])=>'<option value="'+id+'">'+label+'</option>').join('')+'</select></label></div><div id="addGamesChoices" class="game-picker-grid"></div><footer class="game-picker-footer"><p id="addGamesCount" role="status"></p><p id="addGamesError" role="alert"></p><div class="row"><button class="btn" id="addGamesCancel">'+T('Cancel','取消')+'</button><button class="btn main" id="addGamesSave" disabled>'+T('Add selected games','添加已选游戏')+'</button></div></footer></section>');
  const $=id=>document.getElementById(id),cancel=()=>{closeOv();document.getElementById('personalAllGames')?.focus()};
  function count(){$('addGamesCount').textContent=T('Selected: ','已选：')+pending.size;$('addGamesSave').disabled=!pending.size}
  function draw(){
   const query=$('addGamesSearch').value.trim().toLowerCase(),category=$('addGamesCategory').value;
   const ids=available.filter(id=>(category==='all'||window.MindGardenDashboard.category(id)===category)&&(id==='pairs'?'matching pairs memory picture cards 配对游戏 记忆 图片':MG[id].n+' '+MG[id].d+' '+tr(MG[id].n)+' '+tr(MG[id].d)).toLowerCase().includes(query));
   $('addGamesChoices').innerHTML=ids.map(id=>'<article class="personal-game-card">'+catalogueTile(id).replace('data-game=', 'data-pick-game=').replace('<button ', '<button aria-pressed="'+pending.has(id)+'" ').replace('<span class="game-art"','<span class="picker-check" aria-hidden="true">'+(pending.has(id)?'✓':'+')+'</span><span class="game-art"')+window.MindGardenPersonal.info(id)+'</article>').join('')||'<p class="game-picker-empty">'+(available.length?T('No games match your search. Try another category or word.','没有找到符合条件的游戏，请换个关键词或类别。'):T('All games are already in My Games.','所有游戏均已添加到我的游戏。'))+'</p>';
   $('addGamesChoices').querySelectorAll('[data-pick-game]').forEach(b=>b.onclick=()=>{const id=b.dataset.pickGame;if(pending.has(id))pending.delete(id);else pending.add(id);b.setAttribute('aria-pressed',String(pending.has(id)));b.querySelector('.picker-check').textContent=pending.has(id)?'✓':'+';count()});count();
  }
  $('addGamesBack').onclick=cancel;$('addGamesCancel').onclick=cancel;
  $('addGamesSearch').oninput=e=>{if(!e.isComposing)draw()};$('addGamesSearch').oncompositionend=draw;$('addGamesCategory').onchange=draw;
  $('addGamesSave').onclick=()=>{if(save.cp!==owner){cancel();return}const before=me().myGames,c=window.MindGardenPersonal.config();me().myGames={...c,games:[...new Set([...c.games,...pending])]};if(persist()===false){me().myGames=before;$('addGamesError').textContent=T('Games could not be saved. Free device storage and retry.','无法保存游戏，请释放设备存储空间后重试。');return}closeOv();filter='all';search='';renderLibrary();$('personalSummary').textContent=T('Added to My Games.','已添加到我的游戏。');$('personalAllGames').focus()};draw();
 }
 function renderLibrary(searchOnly=false){
  library.querySelectorAll('.zw,.decks,.levels,.garden,.sub,h2.sec,.tip').forEach(el=>{if(!el.closest('#libraryDisplay'))el.classList.add('legacy-library')});
  let panel=document.getElementById('libraryDisplay');if(!panel){panel=document.createElement('div');panel.id='libraryDisplay';library.insertBefore(panel,library.firstChild)}
  const selected=window.MindGardenPersonal?.config().games||[],isMine=collection==='my';
  const source=isMine?selected:['pairs',...Object.keys(MG)];
  const keys=source.filter(id=>(filter==='all'||(id==='pairs'?'memory':META[id]||'logic')===filter)&&(id==='pairs'?'matching pairs memory picture cards 配对游戏 记忆 图片':MG[id].n+' '+MG[id].d+' '+tr(MG[id].n)+' '+tr(MG[id].d)).toLowerCase().includes(search.toLowerCase()));
  const content='<header class="library-heading"><h1>'+T(isMine?'My Games':'All Games',isMine?'我的游戏':'所有游戏')+' <small id="libraryCount" aria-live="polite">('+keys.length+')</small></h1><div class="library-tabs"><button id="libraryAllGames" class="btn'+(!isMine?' main':'')+'"'+(!isMine?' aria-current="page"':'')+'>'+T('All Games','所有游戏')+'</button><button id="libraryMyGames" class="btn'+(isMine?' main':'')+'"'+(isMine?' aria-current="page"':'')+'>'+T('My Games','我的游戏')+'</button></div></header><div class="game-filterbar"><label class="search-field"><span class="search-symbol" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="10" cy="10" r="7"/><path d="m15 15 6 6"/></svg></span><span class="sr">'+T('Search games','搜索游戏')+'</span><input id="gameSearch" type="search" placeholder="'+T('Search games…','搜索游戏…')+'" value="'+esc(search)+'"></label><label class="library-category">'+T('Category','类别')+' <select id="gameCategory">'+['all',...Object.keys(LABELS).filter(c=>c!=='all').sort((a,b)=>LABELS[a][0].localeCompare(LABELS[b][0],'en'))].map(c=>'<option value="'+c+'"'+(filter===c?' selected':'')+'>'+prettyCat(c)+'</option>').join('')+'</select></label></div><div id="gameCards" class="game-card-grid" data-collection="'+collection+'">'+keys.map(id=>catalogueCard(id,selected.includes(id))).join('')+'</div>'+(!keys.length?'<p class="empty-games">'+(isMine&&!selected.length?T('Choose Add games to build your selection.','选择添加游戏，建立您的游戏组合。'):T('No games match your search. Try another category or word.','没有找到符合条件的游戏，请换个关键词或类别。'))+'</p>':'')+'<footer class="catalogue-footer"><p class="library-foot">'+T('Tap a card to choose settings and play. Tap ⓘ for instructions without starting.','点击卡片选择设置并开始游戏。点击 ⓘ 查看说明，不会启动游戏。')+'</p><div class="catalogue-actions">'+(isMine?'<button class="btn" id="personalAllGames">'+T('+ Add games','＋ 添加游戏')+'</button><button class="btn main" id="personalStart"'+(!selected.length?' disabled':'')+'>'+T('Play my selection','按顺序开始')+' ('+selected.length+')</button>':'')+'</div><p id="personalSummary" role="status"></p><button class="btn" id="personalUndo" hidden>'+T('Undo','撤销')+'</button></footer>';
  if(searchOnly&&document.getElementById('gameCards')){const temp=document.createElement('div');temp.innerHTML=content;document.getElementById('gameCards').replaceWith(temp.querySelector('#gameCards'));panel.querySelector('.empty-games')?.remove();const empty=temp.querySelector('.empty-games');if(empty)document.getElementById('gameCards').after(empty)}else panel.innerHTML=content;
  const input=document.getElementById('gameSearch');input.oninput=e=>{search=input.value;if(!e.isComposing)renderLibrary(true)};input.oncompositionend=()=>{search=input.value;renderLibrary(true)};
  document.getElementById('gameCategory').onchange=e=>{filter=e.target.value;renderLibrary()};
  document.getElementById('libraryAllGames').onclick=()=>openLibrary();
  document.getElementById('libraryMyGames').onclick=()=>window.MindGardenPersonal.myGames();
  document.getElementById('libraryCount').textContent='('+keys.length+')';
  if(isMine){document.getElementById('personalAllGames').onclick=addGames;document.getElementById('personalStart').onclick=()=>window.MindGardenPersonal.playSelection()}
  panel.querySelectorAll('[data-game]').forEach(b=>b.onclick=()=>window.MindGardenPersonal.play(b.dataset.game,collection));
  panel.querySelectorAll('[data-save-game]').forEach(b=>b.onclick=()=>{
   const id=b.dataset.saveGame,old=[...selected],owner=me(),removing=isMine;
   window.MindGardenPersonal.selectGame(id,!removing);renderLibrary();
   document.getElementById('personalSummary').textContent=removing?T('Game removed. Scores are kept.','已移除游戏，成绩保留。'):T('Added to My Games.','已添加到我的游戏。');
   const undo=document.getElementById('personalUndo');undo.hidden=false;undo.onclick=()=>{if(me()!==owner)return;me().myGames={...window.MindGardenPersonal.config(),games:old};persist();renderLibrary()};
   (panel.querySelector('[data-save-game="'+id+'"]')||document.getElementById('personalStart'))?.focus({preventScroll:true});
  });
 }
 function matchingMode(){return '<fieldset class="matching-mode"><legend>'+T('Play mode','游戏模式')+'</legend><div class="row"><button class="btn" data-pair-mode="0" aria-pressed="'+!save.timed+'">'+T('Standard · no time limit','标准 · 不限时')+'</button><button class="btn" data-pair-mode="1" aria-pressed="'+!!save.timed+'">'+T('Timed challenge','限时挑战')+'</button></div><p>'+T('Standard lets you finish at your own pace. Timed adds a countdown and speed stars.','标准模式可按自己的节奏完成。限时模式设倒计时与速度星级。')+'</p></fieldset>'}
 function wireMatchingMode(){document.querySelectorAll('[data-pair-mode]').forEach(b=>b.onclick=()=>{save.timed=Number(b.dataset.pairMode);persist();document.querySelectorAll('[data-pair-mode]').forEach(x=>x.setAttribute('aria-pressed',String(Number(x.dataset.pairMode)===save.timed)))})}
 function showPairs(){const opts=LEVELS.map((v,i)=>'<button class="btn" data-pair-level="'+i+'" '+(i>=save.unlocked?'disabled':'')+'>'+T('Level','第')+' '+(i+1)+(save.lang==='zh'?'关':'')+' · '+v.p+' '+T('pairs','对')+'</button>').join('');
  overlay('<h2>'+T('Matching Pairs','配对游戏')+'</h2><p>'+T('Choose your matching game level.','请选择配对游戏关卡。')+'</p>'+matchingMode()+'<div class="level-buttons">'+opts+'</div><p class="tip">'+T('Unlock additional levels by finishing earlier ones.','完成前面的关卡后可解锁后续关卡。')+'</p><div class="row"><button id="pairBack" class="btn">'+T('Back','返回')+'</button></div>');
  wireMatchingMode();document.querySelectorAll('[data-pair-level]').forEach(b=>b.onclick=()=>start(Number(b.dataset.pairLevel)));
  document.getElementById('pairBack').onclick=closeOv;
 }
 function switchPage(p){page=p;dash.classList.toggle('hidden',p!=='dashboard');progressStrip.classList.toggle('hidden',p!=='dashboard');library.classList.toggle('hidden',p!=='library');top.classList.add('hidden');legacyNav.classList.add('hidden');if(p==='library')renderLibrary();else {renderWelcome();renderProgress()}buildNav();window.scrollTo({top:0,behavior:'instant'})}
 const oldShow=window.show;window.show=function(which){oldShow(which);if(which==='home'&&daily)daily=null;nav.classList.toggle('hidden',which!=='home');if(which==='home')switchPage(page)};
 const oldRender=window.renderHome;window.renderHome=function(){oldRender();if(page==='dashboard'){renderWelcome();renderProgress()}else renderLibrary();buildNav()};
 function dailyGame(type){return type==='pairs'?{n:T('Matching Pairs','配对游戏'),d:T('Find the matching picture cards.','找出相同的图片卡片。')}:MG[type]}
 function startDaily(){const plan=window.MindGardenPractice.select(me(),['pairs',...Object.keys(MG).filter(k=>!['pets','today','localnews','gardenrhythm','followgardener'].includes(k)&&!window.MindGardenCommercial?.has(k))],today());daily={plan,types:plan.map(x=>x.type),index:0,active:false};dailyIntro()}
 function dailyIntro(){
  if(!daily)return;
  const type=daily.types[daily.index];
  window.MindGardenPersonal.setup(type,undefined,'all');
  // Activate only on Begin; settings changes must not add another setup step.
  daily.active=true;
 }
 function completeDaily(type){if(window.MindGardenPersonal?.session?.practice)return false;if(!daily||!daily.active||daily.types[daily.index]!==type)return false;daily.active=false;const completed=daily.index+1;
  if(completed===3){daily=null;overlay('<p class="daily-progress">🌻 '+T('Daily journey complete','今日活动完成')+'</p><h2>'+T('Wonderful work!','做得真棒！')+'</h2><p>'+T('You completed three different activities. Enjoy a rest or browse more games.','您完成了三项不同的活动，可以休息或探索更多游戏。')+'</p><div class="row"><button class="btn main" id="dailyHome">'+T('Return to my garden','返回花园')+'</button></div>');document.getElementById('dailyHome').onclick=()=>{mg=null;toHome();switchPage('dashboard')}}
  else{daily.index++;overlay('<p class="daily-progress">✓ '+completed+'/3 '+T('completed','已完成')+'</p><h2>'+T('Well done!','做得好！')+'</h2><p>'+T('Next activity: ','下一项：')+esc(dailyGame(daily.types[daily.index]).n)+'</p><div class="row"><button class="btn main" id="dailyNext">'+T('Next activity','下一项')+'</button><button class="btn" id="dailyRest">'+T('Finish for today','今日结束')+'</button></div>');document.getElementById('dailyNext').onclick=dailyIntro;document.getElementById('dailyRest').onclick=()=>{daily=null;mg=null;toHome();switchPage('dashboard')}}
  dailyResultLayout();
  return true;
 }
 function dailyResultLayout(){
  const box=document.getElementById('box'),next=document.getElementById('dailyNext'),home=document.getElementById('dailyHome')||document.getElementById('dailyRest');
  const section=document.createElement('section');section.id='dailyResult';const footer=document.createElement('footer');footer.className='result-footer';
  if(next){next.innerHTML='<span>'+T('Next game','下一个游戏')+'</span>'+icon('next');next.parentElement.classList.add('daily-result-primary');}
  home.innerHTML=icon('home');home.setAttribute('aria-label',T('Finish for today and return home','结束今日活动并返回主页'));home.title=T('Home','主页');home.classList.remove('main');
  const games=document.createElement('button');games.className='btn';games.id='dailyGames';games.innerHTML=icon('grid')+'<span>'+T('Games','游戏')+'</span>';games.onclick=()=>{daily=null;mg=null;closeOv();toHome();switchPage('library')};
  footer.append(games,home);section.append(footer);box.append(section);window.MindGardenMenuHistory?.clear();
 }
 const oldDone=window.mdone;window.mdone=function(){const type=mg?.t;oldDone();completeDaily(type)};
 window.MindGardenDaily={complete:completeDaily,get position(){return daily?{index:daily.index,total:daily.types.length,type:daily.types[daily.index]}:null},get plan(){return daily?.plan.map(x=>({...x}))||[]}};

 window.MindGardenDashboard={categories:()=>Object.keys(LABELS).filter(k=>k!=='all').sort((a,b)=>LABELS[a][0].localeCompare(LABELS[b][0])).map(k=>[k,prettyCat(k)]),category:id=>id==='pairs'?'memory':META[id]||'memory',gameCard,home:()=>switchPage('dashboard'),library:()=>openLibrary(),myGames:()=>openLibrary('my'),refresh:()=>{renderWelcome();renderProgress();if(page==='library')renderLibrary();buildNav()}};
 // Preserve the dynamic garden generated by index.html and expose it below the welcome headline.
 renderWelcome();renderProgress();switchPage('dashboard');
})();
